const rows = $input.all().map(i => i.json);
const total = rows[0]?.total_open ?? 0;
const newToday = rows[0]?.new_today ?? 0;

let html = `<h3>IT Ops – Rental Risk Daily Summary</h3>`;
html += `<p><b>${total}</b> rental assets currently flagged as linked to a resigned employee`;
html += newToday > 0 ? ` (<b>${newToday}</b> new today).</p>` : `.</p>`;
html += `<table border="1" cellpadding="6" cellspacing="0"><tr><th>Vendor</th><th>Flagged</th><th>Lost</th></tr>`;
for (const r of rows) {
  html += `<tr><td>${r.vendor_name}</td><td>${r.flagged}</td><td>${r.lost}</td></tr>`;
}
html += `</table>`;

return [{ json: { subject: `IT Ops Rental Risk Summary – ${total} flagged`, html } }];
